//
//  Fixture.swift
//  SwiftMoonTests
//
//  Loads Fixtures/new_moons_de440s.json, the JPL DE440s reference generated by
//  scripts/lunar-validation/generate_fixture.py (ADR 3, Option C as test oracle).
//

import Foundation

struct Fixture: Decodable, Sendable {
    struct NewMoon: Decodable, Sendable {
        let k: Int
        let jdTT: Double
        let unixUT1: Double
        let deltaT: Double
    }

    struct IlluminationSample: Decodable, Sendable {
        let jdTT: Double
        let unixUT1: Double
        let fraction: Double
        let elongation: Double
    }

    let newMoons: [NewMoon]
    let illumination: [IlluminationSample]

    static let shared: Fixture = {
        guard
            let url = Bundle.module.url(
                forResource: "new_moons_de440s",
                withExtension: "json",
                subdirectory: "Fixtures"
            )
        else {
            fatalError("Fixtures/new_moons_de440s.json missing from test bundle")
        }
        do {
            return try JSONDecoder().decode(Fixture.self, from: Data(contentsOf: url))
        } catch {
            fatalError("Cannot decode fixture: \(error)")
        }
    }()
}

/// Builds a UTC date from components.
func utc(_ y: Int, _ mo: Int, _ d: Int, _ h: Int = 0, _ mi: Int = 0, _ s: Int = 0) -> Date {
    var calendar = Calendar(identifier: .gregorian)
    calendar.timeZone = TimeZone(identifier: "UTC")!
    return calendar.date(from: DateComponents(year: y, month: mo, day: d, hour: h, minute: mi, second: s))!
}

/// A Gregorian calendar pinned to a time zone.
func calendar(_ identifier: String) -> Calendar {
    var calendar = Calendar(identifier: .gregorian)
    calendar.timeZone = TimeZone(identifier: identifier)!
    return calendar
}
